<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/workspace.php';$user=require_role(['farmer','buyer']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$paymentId=(int)($_POST['payment_id']??0);$action=normalize_text($_POST['payment_action']??'',30);if($action==='record'){$orderId=(int)($_POST['order_id']??0);$order=order_for_actor($orderId,$user,true);if($user['role_slug']!=='buyer'||$order===null||(int)$order['buyer_id']!==(int)$user['id']||in_array($order['status'],['pending','cancelled'],true))throw new RuntimeException('That order is not eligible for a payment record.');$method=normalize_text($_POST['payment_method']??'',80);if(!in_array($method,['cash_on_delivery','bank_transfer','mobile_wallet'],true))throw new RuntimeException('Choose a supported local payment method.');$reference=normalize_text($_POST['external_reference']??'',160);db()->prepare('INSERT INTO payments(order_id,payer_id,payee_id,amount,payment_method,external_reference,status) VALUES(:order_id,:payer,:payee,:amount,:method,:reference,"pending")')->execute(['order_id'=>$orderId,'payer'=>$order['buyer_id'],'payee'=>$order['farmer_id'],'amount'=>$order['total_amount'],'method'=>$method,'reference'=>$reference?:null]);$paymentId=(int)db()->lastInsertId();create_notification((int)$order['farmer_id'],'payment_recorded','Payment record awaiting confirmation','A buyer recorded payment instructions for order '.$order['reference_code'].'.','payments.php','payment',$paymentId);}elseif($action==='confirm'){$payment=fetch_one('SELECT p.*,o.reference_code FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.id=:id AND p.payee_id=:user AND p.status="pending" LIMIT 1',['id'=>$paymentId,'user'=>$user['id']]);if($payment===null)throw new RuntimeException('That pending payment is not available for confirmation.');execute_query('UPDATE payments SET status="paid",paid_at=NOW() WHERE id=:id',['id'=>$paymentId]);create_notification((int)$payment['payer_id'],'payment_confirmed','Payment confirmed','The farmer confirmed receipt for order '.$payment['reference_code'].'.','payments.php','payment',$paymentId);}else throw new RuntimeException('That transaction action is not available.');audit_log((int)$user['id'],'payment_'.$action,'payments',$paymentId);flash('success',$action==='confirm'?'Payment receipt confirmed.':'Payment instructions recorded; funds are not processed by this application.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('payments.php');}
$orders=$user['role_slug']==='buyer'?fetch_all('SELECT id,reference_code,total_amount FROM orders WHERE buyer_id=:user AND status NOT IN("pending","cancelled") ORDER BY created_at DESC',['user'=>$user['id']]):[];$payments=fetch_all('SELECT p.*,o.reference_code,payer.full_name AS payer_name,payee.full_name AS payee_name FROM payments p JOIN orders o ON o.id=p.order_id JOIN users payer ON payer.id=p.payer_id JOIN users payee ON payee.id=p.payee_id WHERE p.payer_id=:payer_user OR p.payee_id=:payee_user ORDER BY p.created_at DESC',['payer_user'=>$user['id'],'payee_user'=>$user['id']]);workspace_open('Transaction history','payments');
?>
<?php if($user['role_slug']==='buyer'):?><section class="workspace-section"><div class="workspace-section-header"><div><h2>Record a local payment instruction</h2><p>This ledger does not move money. It records the agreed cash, bank, or wallet method; the farmer must separately confirm receipt.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="payment_action" value="record"><label>Order<select name="order_id" required><option value="">Choose order</option><?php foreach($orders as $order):?><option value="<?= (int)$order['id'] ?>"><?= e($order['reference_code']) ?> · Rs. <?= number_format((float)$order['total_amount'],2) ?></option><?php endforeach;?></select></label><label>Method<select name="payment_method" required><option value="cash_on_delivery">Cash on delivery</option><option value="bank_transfer">Bank transfer</option><option value="mobile_wallet">Mobile wallet</option></select></label><label>Reference (optional)<input name="external_reference" maxlength="160"></label><button class="button button-primary" type="submit">Record instruction</button></form></section><?php endif;?>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Recorded transactions</h2><p>Account-scoped payment evidence and receipt status.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Parties</th><th>Amount</th><th>Method / reference</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($payments===[]):?><tr><td colspan="6">No transaction records yet.</td></tr><?php else:foreach($payments as $payment):?><tr><td><?= e($payment['reference_code']) ?></td><td><?= e($payment['payer_name']) ?> → <?= e($payment['payee_name']) ?></td><td>Rs. <?= number_format((float)$payment['amount'],2) ?></td><td><?= e(order_status_label($payment['payment_method']??'Not set')) ?><br><span class="muted"><?= e($payment['external_reference']??'No external reference') ?></span></td><td><span class="status-pill <?= e($payment['status']) ?>"><?= e(ucfirst($payment['status'])) ?></span></td><td><?php if($user['role_slug']==='farmer'&&$payment['status']==='pending'):?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="payment_action" value="confirm"><input type="hidden" name="payment_id" value="<?= (int)$payment['id'] ?>"><button class="button button-quiet" type="submit">Confirm funds received</button></form><?php else:?><span class="muted">No action</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php workspace_close(); ?>
